for m in range(2,16):
 for ar in range(m):
  for bc in range(m):
   for d in range(m):
    for e in range(m):
     # linear + bilinear polynomial
     scores=[]
     vals=[]
     for r,c,v in samples:
      q=(ar*r+bc*c+d*r*c+e)%m
      vals.append((q,v))
     # each residue can be selected in an arbitrary subset; score of best subset
     counts=[ [0,0] for _ in range(m)]
     for q,v in vals: counts[q][int(v)]+=1
     score=sum(max(a,b) for a,b in counts)
     if score==len(samples):
      print('exact',m,ar,bc,d,e,counts); raise SystemExit
