for form in ['abs','dist','quad']:
 for a in range(-2,3):
  for b in range(-2,3):
   for condition in ['andzero','andnonzero','xorzero','xor_nonzero','or_power','sum_power']:
    hit=0
    for r,c,v in samples:
     if form=='abs': x,y=r+a,c+b
     elif form=='dist': x,y=abs(4-r)+a,abs(6-c)+b
     else: x,y=(4-r if r<4 else r-4)+a,(6-c if c<6 else c-6)+b
     if condition=='andzero': p=(x&y)==0
     elif condition=='andnonzero': p=(x&y)!=0
     elif condition=='xorzero': p=x==y
     elif condition=='xor_nonzero': p=x!=y
     elif condition=='or_power': p=(x|y)>0 and ((x|y)&((x|y)-1)==0)
     else: p=(x+y)>0 and ((x+y)&(x+y-1)==0)
     hit+=p==v
    if hit>len(samples)*.82: print(form,a,b,condition,hit)

